 y=np.array([mod.accel(t,w,u,np.array(p),f) if hasattr(mod,'accel') else mod.acc(t,w,u,np.array(p),f) for t,w,u in df[['theta','omega','u']].to_numpy()])
 r=y-df.domega.to_numpy();m=abs(df.omega.to_numpy())>1
